style.css:
@-moz-document domain("roblox.com") {
/* Main Background */
    body {
        background-color: #c4d3e0 !important;
        font-family: Verdana, sans-serif !important;
    }

    /* Navigation Bar */
    nav, .navbar, #navigation, .header {
        background-color: #0d2a59 !important;
        color: white !important;
        border-bottom: 2px solid #0b1e40 !important;
    }

    nav a, .navbar a, .header a {
        color: white !important;
        font-weight: bold !important;
        text-transform: none !important;
    }

    /* Buttons */
    button, .btn, input[type="submit"] {
        background-color: #1f4e99 !important;
        color: white !important;
        border: 1px solid #0b1e40 !important;
        font-family: Verdana, sans-serif !important;
    }

    /* Old-style Header Titles */
    h1, h2, h3 {
        color: #0d2a59 !important;
        font-family: Verdana, sans-serif !important;
    }

    /* Remove Modern Stuff */
    .game-card-container, .avatar-card-container, .home-left-content, .notification-stream {
        border-radius: 0 !important;
        box-shadow: none !important;
        background-color: #ffffff !important;
    }

    /* Classic Logo Replacement (Optional - requires custom image) */
    .navbar-brand img {
        content: url("https://upload.wikimedia.org/wikipedia/en/6/60/Roblox_Logo_2008.png") !important;
        height: 40px !important;
    }

    /* Footer */
    footer {
        background-color: #0d2a59 !important;
        color: white !important;
    }
}
